import {progress,level} from './engine.js';
import {money} from './economy.js';
import {previewSound,transferTick} from './sound.js';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showReward({name,before,after,xp,coins,sounds,reduced=false}){
 const modal=document.createElement('dialog');modal.className='reward-panel';const reduce=reduced||matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(reduce)modal.classList.add('quiet');modal.innerHTML=`<div class="reward-heading"><span class="eyebrow">QUEST COMPLETE</span><h2>${esc(name)}</h2><p>Progress saved.</p></div><div class="reward-level-slot"><div class="reward-level-up" aria-hidden="true">LEVEL UP</div></div><div class="reward-transfer"><section class="reward-source"><small>EARNED</small><strong>+${xp} XP</strong><strong>${money(coins)}</strong></section><div class="reward-lane" aria-hidden="true"></div><section class="reward-target"><small>YOUR TOTAL</small><b data-total-xp></b><b data-balance></b><span data-level></span></section></div><div class="reward-progress"><i></i></div><p data-level-progress></p><p class="sr-only" role="status">${esc(name)} earned ${xp} XP and ${money(coins)}. Total ${after.xp} XP and ${money(after.coins)}.</p><p class="reward-skip-hint">Tap to skip · Esc to close</p>`;
 document.body.append(modal);modal.showModal();let frame,timer,closed=false,lastPacket=-1,lastLevel=level(before.xp),lastEffectEnd=0;const play=(type)=>previewSound(type,sounds).catch(()=>{});play('complete');if(xp)play('xp');if(coins&&sounds.credits.mode==='custom')play('credits');
 const finish=()=>{if(closed)return;closed=true;cancelAnimationFrame(frame);clearTimeout(timer);document.removeEventListener('click',outside,true);modal.close();modal.remove();};modal.addEventListener('click',finish);modal.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();finish();}});document.addEventListener('click',outside,true);function outside(e){if(!modal.contains(e.target)){e.preventDefault();e.stopPropagation();finish();}}modal.addEventListener('cancel',e=>{e.preventDefault();finish();});modal.addEventListener('close',()=>{if(!closed)finish();});
 const paint=t=>{const earnedXP=Math.floor(xp*t),balance=before.coins+coins*t,p=progress(before.xp+earnedXP);modal.querySelector('[data-total-xp]').textContent=(before.xp+earnedXP).toLocaleString()+' XP';modal.querySelector('[data-balance]').textContent=money(before.coins+(t===1?coins:Math.floor(coins*t)));modal.querySelector('[data-level]').textContent='LEVEL '+p.level;modal.querySelector('[data-level-progress]').textContent=`${p.current} / ${p.total} XP to level ${p.level+1}`;modal.querySelector('.reward-progress i').style.width=(p.current/p.total*100)+'%';if(p.level>lastLevel){lastLevel=p.level;lastEffectEnd=performance.now()+1400;modal.classList.add('leveled');play('level');if(!reduce)for(let i=0;i<12;i++){const dot=document.createElement('i');dot.className='level-spark';dot.style.setProperty('--angle',i*30+'deg');modal.append(dot);}}};
 if(reduce){paint(1);timer=setTimeout(finish,3000);return;}
 const start=performance.now(),duration=2400;paint(0);const animate=now=>{if(closed)return;const t=Math.min(1,(now-start)/duration),ease=t*t*(3-2*t);paint(ease);const packet=Math.min(11,Math.floor(t*12));if(packet>lastPacket){lastPacket=packet;lastEffectEnd=Math.max(lastEffectEnd,now+600);if(coins>0)transferTick(sounds).catch(()=>{});for(const [symbol,kind] of [[xp?'◆':'','xp'],[coins?'€$':'','cash']])if(symbol){const particle=document.createElement('span');particle.className='reward-particle '+kind;particle.textContent=symbol;particle.style.setProperty('--lift',(packet%3-1)*24+'px');modal.querySelector('.reward-lane').append(particle);particle.addEventListener('animationend',()=>particle.remove(),{once:true});}}if(t<1)frame=requestAnimationFrame(animate);else{paint(1);timer=setTimeout(finish,Math.max(0,lastEffectEnd-performance.now())+3000);}};frame=requestAnimationFrame(animate);
}
